// The institutional requirements register (docs/INSTITUTIONAL_REQUIREMENTS.md,
// rows in docs/requirements/requirements.json, generated by
// app/scripts/requirements/extract.py) is binding (plan §5, Traceability):
// every section of the specification has rows, and every row has an id, its
// spec lines, a status and the step that delivers it. The same holds for the
// forms catalogue (docs/forms-catalogue/*.md: one 13-part series and its
// supplement, parts 14–22 and contracts for parts 5–13): every
// catalogue ID has a row with a step, and every part, section and sub-section
// heading has at least one row (headings found by the rule of
// app/scripts/requirements/parse_catalogue.py, restated below).

import { describe, expect, it } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import { createHash } from 'crypto';

const ROOT = path.resolve(__dirname, '../../../..');
const SPEC = fs.readFileSync(path.join(ROOT, 'docs/INSTITUTIONAL_ARCHITECTURE_SPEC.md'), 'utf8').split('\n');
interface Row { id: string; source: string; part: number; section: string; lines: string; status: string; step: string; also_steps?: string; catalogue_id?: string; kind?: string; category?: string; contract?: string; form_status?: string; scope_flag?: string }
const ALL: Row[] = JSON.parse(fs.readFileSync(path.join(ROOT, 'docs/requirements/requirements.json'), 'utf8'));
const SPEC_SOURCE = 'docs/INSTITUTIONAL_ARCHITECTURE_SPEC.md';
const ROWS = ALL.filter(r => r.source === SPEC_SOURCE);
const CAT_DIR = 'docs/forms-catalogue';
// The catalogue's source files (the README, the owner's direction and the generated gap report are not catalogue text).
const CAT_FILES = fs.readdirSync(path.join(ROOT, CAT_DIR)).filter(f => /^(FIELD-SERIES|PARTS|SUPPLEMENT)-.*\.md$/.test(f)).sort();
const CAT_ROWS = ALL.filter(r => r.source.startsWith(`${CAT_DIR}/`));

const STATUSES = ['Met', 'Partial', 'Not yet', 'Platform rule stricter', 'Country decision', 'Lower priority'];
const CAT_STATUSES = [...STATUSES, 'Legal review'];
const FORM_STATUSES = ['catalogued', 'contract_missing', 'contract_draft', 'under_review', 'blocked', 'excluded', 'approved', 'production'];
const STEPS = /^(I0\.2|I(1[0-3]|[1-9])|Throughout)$/;
const DONE = ['Met', 'Platform rule stricter', 'Country decision'];

/** Numbered and lettered section headings, with the section id the extractor gives them (parse_spec.py). */
function headings(): { line: number; part: number; id: string; title: string }[] {
  const out: { line: number; part: number; id: string; title: string }[] = [];
  let part = 0, letter: string | null = null, num: string | null = null, sub: string | null = null;
  SPEC.forEach((raw, i) => {
    const n = i + 1, s = raw.trim();
    if (n < 30) return; // provenance note, not specification text
    const p = /^## .*Part (\d) of 6/.exec(s);
    if (p) { part = Number(p[1]); letter = num = sub = null; return; }
    let m = /^#### (\d+)\.(\d+) (.+)$/.exec(s);
    if (m) { sub = `${m[1]}.${m[2]}`; out.push({ line: n, part, id: sub, title: m[3]! }); return; }
    m = /^([A-M])\. (.+)$/.exec(s);
    if (m && part >= 2 && s.length < 100) { letter = m[1]!; num = null; out.push({ line: n, part, id: letter, title: m[2]! }); return; }
    m = /^(\d+)\. ([^.]+)$/.exec(s);
    if (m && part >= 1 && s.length < 100) {
      num = m[1]!; sub = null;
      out.push({ line: n, part, id: part === 1 ? num : letter ? `${letter}.${num}` : num, title: m[2]! });
    }
  });
  return out;
}

/** Catalogue headings: the rule of parse_catalogue.py headings()/is_stage(). */
const NUM = /^(\d+)\. (.+)$/;
function isStage(lines: string[], i: number): boolean {
  const s = lines[i]!.trim();
  if (!NUM.test(s) || s.endsWith('.')) return false;
  const nxt = lines[i + 1] ?? '';
  if (nxt.trim()) return false;
  let k = i + 1;
  while (k < lines.length && !lines[k]!.trim()) k++;
  if (k >= lines.length) return false;
  if (/^ {3}/.test(nxt)) return true;
  const d = lines[k]!.trim();
  return !(NUM.test(d) || /^([A-D])\. (.+)$/.test(d) || /^0(\d)$/.test(d) || /^(\d+)\.(\d+) (\S.*)$/.test(d) || d.includes('\t') || d.startsWith('- ') || !d.endsWith('.'));
}
function catalogueHeadings(lines: string[]): { line: number; part: number; id: string; title: string }[] {
  const out: { line: number; part: number; id: string; title: string }[] = [];
  let part: number | null = null, cur = 0, field = false, prev = '';
  lines.forEach((raw, i) => {
    const s = raw.trim();
    const p = /^Part (\d+)(?: of 13)?(?: —|\.) (.+)$/.exec(s);
    if (p && !s.endsWith('.')) { part = Number(p[1]); cur = 0; field = false; out.push({ line: i + 1, part, id: 'part', title: p[2]! }); }
    else if (part !== null) {
      const m = /^(\d+)\. (.+)$/.exec(s), pm = NUM.exec(prev);
      if (!field && m && Number(m[1]) === cur + 1 && !s.endsWith('.') && !m[2]!.includes(':') && s.length < 100 && !isStage(lines, i)
        && !(pm && Number(pm[1]) === cur) && !prev.endsWith(':')) {
        cur = Number(m[1]); out.push({ line: i + 1, part, id: String(cur), title: m[2]! });
      } else {
        const sm = /^(\d+)\.(\d+) (\S.*)$/.exec(s);
        if (sm && cur > 0 && Number(sm[1]) === cur) out.push({ line: i + 1, part, id: `${sm[1]}.${sm[2]}`, title: sm[3]! });
        else if (sm && cur === 0 && Number(sm[1]) === part) { field = true; out.push({ line: i + 1, part, id: `${sm[1]}.${sm[2]}`, title: sm[3]! }); }
      }
    }
    if (s) prev = s;
  });
  return out;
}
/** Catalogue IDs: first cell of a table row, "- id — text" and bare "- country.…" list items, "ID: … · " group lines. */
function catalogueIds(lines: string[]): string[] {
  const start = lines.indexOf('---') + 1, ids = new Set<string>();
  lines.forEach((l, i) => {
    if (i < start) return;
    const m = /^((?:[A-Z]{2,5}-)+\d{3}|[a-z][a-z0-9_]*(?:\.[a-z0-9_-]+)+)\t/.exec(l) ?? /^- ([a-z][a-z0-9_]*(?:\.[a-z0-9_]+)+) — /.exec(l)
      ?? /^- (country\.[a-z0-9_.]+)$/.exec(l) ?? /^ID: (\S+) · /.exec(l);
    if (m) ids.add(m[1]!);
  });
  return [...ids];
}

describe('institutional requirements register', () => {
  it('has a row for every numbered and lettered section of the specification', () => {
    const hs = headings();
    expect(hs.length).toBeGreaterThan(150);
    const missing = hs.filter(h => !ROWS.some(r => r.part === h.part && (r.section === h.id || r.section.startsWith(`${h.id}.`))))
      .map(h => `Part ${h.part} ${h.id} ${h.title} (line ${h.line})`);
    expect(missing).toEqual([]);
  });

  it('gives every row an id, spec lines within the specification and a status', () => {
    const bad = ROWS.filter(r => {
      const ls = /^(\d+)(?:-(\d+))?$/.exec(r.lines ?? '');
      return !r.id || !ls || Number(ls[1]) < 30 || Number(ls[2] ?? ls[1]) > SPEC.length || !STATUSES.includes(r.status);
    }).map(r => r.id || JSON.stringify(r).slice(0, 80));
    expect(bad).toEqual([]);
    expect(new Set(ROWS.map(r => r.id)).size).toBe(ROWS.length);
  });

  it('assigns every row to a plan step; only met, stricter or country rows carry "—"', () => {
    const bad = ROWS.filter(r => !(STEPS.test(r.step) || (r.step === '—' && DONE.includes(r.status)))).map(r => `${r.id} ${r.status} ${r.step}`);
    expect(bad).toEqual([]);
  });
});

describe('forms catalogue in the register', () => {
  it('reads every catalogue file and keeps every row in a file it names', () => {
    expect(CAT_FILES.length).toBeGreaterThanOrEqual(6);
    expect(CAT_ROWS.length).toBeGreaterThan(5000);
    expect(ALL.length).toBe(ROWS.length + CAT_ROWS.length);
    expect(new Set(ALL.map(r => r.id)).size).toBe(ALL.length);
  });

  it('gives every catalogue ID of every file a row with a status and a plan step', () => {
    let total = 0;
    const missing: string[] = [];
    for (const f of CAT_FILES) {
      const ids = catalogueIds(fs.readFileSync(path.join(ROOT, CAT_DIR, f), 'utf8').split('\n'));
      total += ids.length;
      for (const id of ids) {
        const r = CAT_ROWS.find(x => x.source === `${CAT_DIR}/${f}` && x.catalogue_id === id);
        if (!r || !CAT_STATUSES.includes(r.status) || !(STEPS.test(r.step) || (r.step === '—' && DONE.includes(r.status)))) missing.push(`${f} ${id}`);
      }
    }
    expect(total).toBeGreaterThan(2000);
    expect(missing).toEqual([]);
  });

  it('has a row for every part, section and sub-section heading of each catalogue file', () => {
    const missing: string[] = [];
    let n = 0;
    for (const f of CAT_FILES) {
      const hs = catalogueHeadings(fs.readFileSync(path.join(ROOT, CAT_DIR, f), 'utf8').split('\n'));
      n += hs.length;
      const rows = CAT_ROWS.filter(r => r.source === `${CAT_DIR}/${f}`);
      for (const h of hs) {
        const ok = h.id === 'part' ? rows.some(r => r.part === h.part)
          : rows.some(r => r.part === h.part && (r.section === h.id || r.section.startsWith(`${h.id}.`)));
        if (!ok) missing.push(`${f} part ${h.part} ${h.id} ${h.title} (line ${h.line})`);
      }
    }
    const parts = new Set(CAT_ROWS.map(r => r.part).filter(p => p > 0));
    expect([...parts].sort((a, b) => a - b)).toEqual(Array.from({ length: 22 }, (_, i) => i + 1));
    expect(n).toBeGreaterThan(300);
    expect(missing).toEqual([]);
  });

  it('gives every catalogue row lines within its file, a status and a plan step', () => {
    const len = new Map<string, number>();
    const bad = CAT_ROWS.filter(r => {
      if (!len.has(r.source)) len.set(r.source, fs.readFileSync(path.join(ROOT, r.source), 'utf8').split('\n').length);
      const ls = /^(\d+)(?:-(\d+))?$/.exec(r.lines ?? '');
      return !r.id || !ls || Number(ls[1]) < 1 || Number(ls[2] ?? ls[1]) > len.get(r.source)! || !CAT_STATUSES.includes(r.status)
        || !(STEPS.test(r.step) || (r.step === '—' && DONE.includes(r.status)));
    }).map(r => `${r.id} ${r.status} ${r.step} ${r.lines}`);
    expect(bad).toEqual([]);
  });

  it('gives every catalogue form its field contract in the form library (I1-catalogue) beside its sector step', () => {
    const bad = CAT_ROWS.filter(r => r.kind === 'catalogue' && r.catalogue_id && !/^(CFG-|country\.|REG-|EX-|HX-|JX-|INT-|civicos\.|iso\.)/.test(r.catalogue_id)
      && !(r.also_steps ?? '').split(',').includes('I1-catalogue')).map(r => r.id);
    expect(bad).toEqual([]);
  });

  it('says for every catalogue form whether its own field contract has been given', () => {
    const forms = CAT_ROWS.filter(r => r.category === 'form');
    expect(forms.length).toBeGreaterThan(2000);
    expect(forms.filter(r => r.contract !== 'given' && r.contract !== 'not yet given').map(r => r.id)).toEqual([]);
  });
});

// Owner's direction 2026-10-21 (docs/forms-catalogue/DIRECTION-2026-10-21-REGISTER-FIRST.md): register first; one form status per
// form, derived from the files and the scope list (docs/requirements/form-scope.json); nothing approved or in production; every
// contract matched to a registered form; the gap report generated and current.
const SCOPE = JSON.parse(fs.readFileSync(path.join(ROOT, 'docs/requirements/form-scope.json'), 'utf8')) as {
  forms: { source: string; id: string; scope: string; rule: string }[]; non_form_contracts: { source: string; id: string }[];
};
const GAP = JSON.parse(fs.readFileSync(path.join(ROOT, CAT_DIR, 'gap-report.json'), 'utf8')) as {
  sources: Record<string, string>; form_status: Record<string, number>; production_candidates: string[];
  contracts: { unmatched: unknown[]; ambiguous: unknown[] }; verified: Record<string, number>; reported: Record<string, number>;
};
const FORMS = CAT_ROWS.filter(r => r.category === 'form');

describe('forms register (owner\'s direction 2026-10-21)', () => {
  it('gives every form exactly one form status, and none is approved or in production', () => {
    expect(FORMS.filter(r => !FORM_STATUSES.includes(r.form_status ?? '')).map(r => r.id)).toEqual([]);
    expect(FORMS.filter(r => r.form_status === 'approved' || r.form_status === 'production').map(r => r.id)).toEqual([]);
    expect(GAP.production_candidates).toEqual([]);
  });

  it('applies the binding scope list: excluded and legal-review forms are never approved or in production', () => {
    for (const e of SCOPE.forms) expect(e.rule.length).toBeGreaterThan(10);
    const bad: string[] = [];
    for (const e of SCOPE.forms.filter(x => x.scope !== 'allowed')) {
      const rows = FORMS.filter(r => r.source === e.source && r.catalogue_id === e.id);
      if (rows.length === 0) bad.push(`${e.id} not in the register`);
      for (const r of rows) {
        const want = e.scope === 'excluded' ? 'excluded' : 'under_review';
        const flag = e.scope === 'excluded' ? 'excluded_pending_scope_review' : 'requires_legal_review';
        if (r.form_status !== want || r.scope_flag !== flag) bad.push(`${r.id} ${r.form_status} ${r.scope_flag}`);
        if (e.scope === 'excluded' && r.status !== 'Platform rule stricter') bad.push(`${r.id} status ${r.status}`);
      }
    }
    expect(bad).toEqual([]);
    // the owner's named exclusions and legal reviews are in the list
    const scoped = (id: string, scope: string) => SCOPE.forms.some(e => e.id === id && e.scope === scope);
    for (const id of ['HLT-PAT-001', 'HLT-ENC-002', 'HLT-REF-003', 'HLT-CARE-008', 'EDU-STD-001', 'EDU-ENR-003', 'EDU-ATT-004', 'EDU-RES-005']) expect(scoped(id, 'excluded')).toBe(true);
    for (const id of ['JUS-PRO-006', 'JUS-COR-008', 'SEC-INT-006', 'SEC-OVS-007', 'ELE-REG-004']) expect(scoped(id, 'requires_legal_review')).toBe(true);
  });

  it('matches every JSON contract in the sources to a registered form (or its field group, or a declared non-form)', () => {
    const unmatched: string[] = [];
    for (const f of CAT_FILES) {
      const src = `${CAT_DIR}/${f}`, lines = fs.readFileSync(path.join(ROOT, src), 'utf8').split('\n');
      for (let i = 0; i < lines.length; i++) {
        if (lines[i] !== '{') continue;
        let j = i;
        while (lines[j] !== '}') j++;
        const obj = JSON.parse(lines.slice(i, j + 1).join('\n')) as { form_id?: string; group_id?: string; fields?: unknown[]; contracts?: { form_id: string }[] };
        const ids = obj.contracts ? obj.contracts.map(c => c.form_id) : obj.fields && !obj.group_id && obj.form_id ? [obj.form_id] : [];
        for (const id of ids) {
          if (SCOPE.non_form_contracts.some(n => n.source === src && n.id === id)) continue;
          if (!FORMS.some(r => r.catalogue_id === id && r.contract === 'given')) unmatched.push(`${f} line ${i + 1}: ${id}`);
        }
        i = j;
      }
    }
    expect(unmatched).toEqual([]);
    expect(GAP.contracts.unmatched).toEqual([]);
    expect(GAP.contracts.ambiguous).toEqual([]);
  });

  it('has a current gap report: generated from these sources and agreeing with the register', () => {
    const sha = (p: string) => createHash('sha256').update(fs.readFileSync(path.join(ROOT, p))).digest('hex');
    const want: Record<string, string> = { 'docs/requirements/form-scope.json': sha('docs/requirements/form-scope.json') };
    for (const f of CAT_FILES) want[`${CAT_DIR}/${f}`] = sha(`${CAT_DIR}/${f}`);
    expect(GAP.sources).toEqual(want);
    const counts: Record<string, number> = {};
    for (const r of FORMS) counts[r.form_status!] = (counts[r.form_status!] ?? 0) + 1;
    expect(GAP.form_status).toEqual(counts);
    expect(fs.existsSync(path.join(ROOT, CAT_DIR, 'GAP-REPORT.md'))).toBe(true);
    expect(Object.keys(GAP.verified).sort()).toEqual(Object.keys(GAP.reported).sort());
  });
});
